def lps(s: str) -> int:
    def helper(low, high, memo={}):
        if (low, high) in memo:
            return memo[(low, high)]
        if low > high:
            return 0
        if low == high:
            return 1
        if s[low] == s[high]:
            memo[(low, high)] = 2 + helper(low + 1, high - 1, memo)
        else:
            memo[(low, high)] = max(helper(low + 1, high, memo), helper(low, high - 1, memo))
        return memo[(low, high)]

    return helper(0, len(s) - 1)

